<?php declare(strict_types=1);use Kulturhus\Verein\TaxCatalog;
$storedPositions=$finance->positions($positionType,$positionId);$positionHistory=$finance->positionHistory($positionType,$positionId);$positionCompact=$positionCompact??false;
$positionDetailsMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$positionDetailsText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\PositionMessages::text($s,$positionDetailsMessages,$v);
$positionDetailsSphere=static fn(string$value):string=>$value===''?$positionDetailsText('Sphäre offen'):(isset(TaxCatalog::costCenters()[$value])?$value.' '.$positionDetailsText(TaxCatalog::costCenters()[$value]):$value.' · '.$positionDetailsText('Auswahl prüfen'));
?>
<?php if($positionCompact):?><details class="card invoice-internal-accounting position-details" data-position-details><summary><strong><?=e($positionDetailsText('Zusätzliche Buchhaltungsangaben'))?></strong><span class="muted"><?=e($positionDetailsText('Nur bei Bedarf'))?></span></summary><?php endif?>
<section class="<?=$positionCompact?'invoice-internal-accounting-content':'card position-details'?>" <?=$positionCompact?'':'data-position-details'?>><div class="section-heading"><h2><?=e($positionDetailsText($positionCompact?'Zusätzliche Buchhaltungsangaben':'Positionen & Kontierung'))?></h2><?php if($finance->canWrite()&&$positionEditable):?><a class="btn btn-outline theme-secondary button secondary" data-edit-position href="<?=e(url($positionRoute+['edit_positions'=>1]))?>"><?=e($positionDetailsText('Positionen bearbeiten'))?></a><?php endif?></div>
<div class="table-scroll"><table class="table"><thead><tr><?php foreach(['Position','Sphäre','Steuerkonto','BU-Schlüssel','Steuer','Brutto']as$column):?><th><?=e($positionDetailsText($column))?></th><?php endforeach?></tr></thead><tbody><?php foreach($storedPositions as$p):?><tr><td><?=e($p['description'])?></td><td><?=e($p['sphere']===''?$positionDetailsText('Noch offen'):$positionDetailsSphere($p['sphere']))?></td><td><?=e($p['account_code']===''?$positionDetailsText('Noch offen'):$p['account_code'].' · '.$p['account_name'])?><small class="block muted"><?=e($p['catalog_year']?$positionDetailsText('Kontenplanbasis SKR42 · {year} · {group}',['year'=>$p['catalog_year'],'group'=>$positionDetailsText(TaxCatalog::GROUPS[$p['account_category']])]):'')?></small></td><td><?=e($p['booking_key']!==''?$p['booking_key']:'–')?></td><td><?=(int)$p['tax_rate']?> %<small class="block muted"><?=e(euro((int)$p['tax_cents']))?></small><?php if(($positionKind??($financeEntry['kind']??''))==='expense'):?><small class="block muted"><?=e($positionDetailsText(\Kulturhus\Verein\InputTaxTreatment::OPTIONS[$p['input_tax']??'unknown']??'Vorsteuerbehandlung prüfen'))?></small><?php endif?></td><td class="amount"><?=e(euro((int)$p['gross_cents']))?></td></tr><?php endforeach?></tbody></table></div>
<div class="position-totals"><span><?=e($positionDetailsText('Netto'))?> <strong><?=e(euro((int)array_sum(array_column($storedPositions,'gross_cents'))-(int)array_sum(array_column($storedPositions,'tax_cents'))))?></strong></span><span><?=e($positionDetailsText('Gesamt'))?> <strong><?=e(euro((int)array_sum(array_column($storedPositions,'gross_cents'))))?></strong></span></div>
<?php if($positionHistory):?><details><summary><?=e($positionDetailsText('Änderungsverlauf ({count})',['count'=>count($positionHistory)]))?></summary>
<?php foreach($positionHistory as$revision):?><article class="position-revision"><strong><?=e($positionDetailsText('Gespeichert'))?></strong> · <?=e($revision['happened_at'])?><p><?=e($revision['reason'])?></p>
<?php foreach(['previous_positions'=>'Vorher','next_positions'=>'Nachher']as$field=>$label):?><p><strong><?=e($positionDetailsText($label))?>:</strong>
<?php foreach(json_decode($revision[$field],true,512,JSON_THROW_ON_ERROR)as$p):?><span class="block"><?=e($p['description'].' · '.euro((int)$p['gross_cents']).' · '.$positionDetailsSphere($p['sphere']).' · '.($p['account_code']!==''?$p['account_code'].' '.$p['account_name']:$positionDetailsText('Steuerkonto offen')).' · '.$p['tax_rate'].' % · BU '.($p['booking_key']??'–').' · '.$positionDetailsText('Vorsteuer:').' '.$positionDetailsText(\Kulturhus\Verein\InputTaxTreatment::OPTIONS[$p['input_tax']??'unknown']??'Ungültig'))?></span><?php endforeach?></p><?php endforeach?></article><?php endforeach?></details><?php endif?></section>
<?php if($positionCompact):?></details><?php endif?>
<?php if($positionType==='goods'||($financeEntry['kind']??'')==='donation'):?><p><a href="?view=settings&amp;tab=donation-forms"><?=e($positionDetailsText('Amtliche Spendenformulare & Stand der Bescheinigungsausgabe →'))?></a></p><?php endif?>
